import JSON

"""
	fresnel( x )

Evaluate the Fresnel integrals `S(x)` and `C(x)` in extended precision.

Below `x = 10`, sum the power series; from there on, use the asymptotic expansions of the auxiliary functions `f` and `g` (Abramowitz and Stegun 7.3.27 and 7.3.28), whose terms shrink far below the working precision before they start to grow.

# Arguments

* `x`: input value

# Examples

``` julia
julia> S, C = fresnel( BigFloat( 1.0 ) );
```
"""
function fresnel( x )
	if x < 10
		a = BigFloat( pi ) / 2 * x^2;
		S = zero( BigFloat );
		C = zero( BigFloat );
		t = one( BigFloat );
		k = 0;
		while k < 10 || abs( t ) > eps( BigFloat )
			if iseven( k )
				C += ( iseven( k ÷ 2 ) ? 1 : -1 ) * t / ( 2*k + 1 );
			else
				S += ( iseven( k ÷ 2 ) ? 1 : -1 ) * t / ( 2*k + 1 );
			end
			k += 1;
			t *= a / k;
		end
		return x * S, x * C;
	end
	w = BigFloat( pi ) * x^2;
	f = one( BigFloat );
	g = one( BigFloat );
	tf = one( BigFloat );
	tg = one( BigFloat );
	for m in 1:60
		tf *= -( 4*m - 3 ) * ( 4*m - 1 ) / w^2;
		tg *= -( 4*m - 1 ) * ( 4*m + 1 ) / w^2;
		f += tf;
		g += tg;
	end
	f /= BigFloat( pi ) * x;
	g /= BigFloat( pi )^2 * x^3;
	s, c = sincos( BigFloat( pi ) / 2 * x^2 );
	return 0.5 - ( f * c ) - ( g * s ), 0.5 + ( f * s ) - ( g * c );
end

"""
	gen( domain, name )

Generate fixture data and write to file.

# Arguments

* `domain`: domain
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = range( 100.0, stop = 1000.0, length = 1000 );
julia> gen( x, "data.json" );
```
"""
function gen( domain, name )
	x = Float64.( Float32.( collect( domain ) ) );
	S = Float64[];
	C = Float64[];
	setprecision( BigFloat, 2048 ) do
		for xi in x
			s, c = fresnel( BigFloat( xi ) );
			push!( S, Float64( s ) );
			push!( C, Float64( c ) );
		end
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("S", S),
		("C", C)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Small values:
x = range( 0.0001, stop = 9.99, length = 1000 );
gen( x, "small.json" );

# Medium values:
x = range( 10.0, stop = 100.0, length = 1000 );
gen( x, "medium.json" );

# Large values:
x = range( 100.0, stop = 36968.0, length = 1000 );
gen( x, "large.json" );

# Huge values:
x = exp10.( range( log10( 40000.0 ), stop = log10( 16777216.0 ), length = 1000 ) );
gen( x, "huge.json" );
